sys_ux_data_broker_transform.script:
function transform(input) {
    // Define the parameters
    var tableName = 'cmdb_ci_server';
    var field1 = 'model_id';
    var field2 = 'serial_number';

    // declare an array
    var dupRecords = [];
    var duplicateCount = 0;

    gs.log("Starting duplicate check for table: " + tableName + " on fields: " + field1 + " and " + field2);

    var duplicateCheck = new GlideAggregate(tableName);
    duplicateCheck.addNotNullQuery(field1);
    duplicateCheck.addNotNullQuery(field2);
    duplicateCheck.groupBy(field1);
    duplicateCheck.groupBy(field2);
    duplicateCheck.addHaving('COUNT', '>', 1); // addHaving func won't work in scope app
    duplicateCheck.query();

    gs.log("Running query to find duplicate combinations");

    while(duplicateCheck.next()) {
        var jsonObj = {}; // declare a json object
        jsonObj[field1] = duplicateCheck[field1].toString();
        jsonObj[field2] = duplicateCheck[field2].toString();
        dupRecords.push(jsonObj);
    }

    var jsonString = JSON.stringify(dupRecords); // convert json object to string
    gs.log("Found " + dupRecords.length + " duplicate combinations");

    var parser = new JSONParser();
    var parsedData = parser.parse(jsonString);
    var length = parsedData.length;

    var result = {
        totalDuplicateCombinations: length,
        totalDuplicateRecords: 0,
        duplicateDetails: []
    };

    for(var i=0; i<length; i++){
        var encodedQuery = field1 + '=' + parsedData[i][field1] + '^' + field2 + '=' + parsedData[i][field2];

        var tableRec = new GlideRecord(tableName);
        tableRec.addEncodedQuery(encodedQuery);
        tableRec.query();

        var count = tableRec.getRowCount();
        var duplicateCount = count - 1; // One is the original, the rest are duplicates
        result.totalDuplicateRecords += duplicateCount;

        var recordDetails = {
            field1Value: parsedData[i][field1],
            field1Display: '',
            field2Value: parsedData[i][field2],
            field2Display: '',
            totalRecords: count,
            duplicateCount: duplicateCount,
            records: []
        };

        // Get display values and record details
        while(tableRec.next()){
            if (recordDetails.field1Display === '') {
                recordDetails.field1Display = tableRec.getDisplayValue(field1);
                recordDetails.field2Display = tableRec.getDisplayValue(field2);
            }

            recordDetails.records.push({
                sys_id: tableRec.getUniqueValue(),
                name: tableRec.getDisplayValue('name'),
                created: tableRec.getValue('sys_created_on')
            });

            gs.info('Duplicate record found: ' + field1 + ' -> ' + tableRec.getDisplayValue(field1) + 
                    ', ' + field2 + ' -> ' + tableRec.getDisplayValue(field2) + 
                    ', Name -> ' + tableRec.getDisplayValue('name'));
        }

        result.duplicateDetails.push(recordDetails);
    }

    gs.log("Total duplicate combinations: " + result.totalDuplicateCombinations);
    gs.log("Total duplicate records: " + result.totalDuplicateRecords);

    // Create the return object following the structure from the first example
    return [
        {
            "data": [
                {
                    "value": result.totalDuplicateRecords.toString(),
                    "change": "0",
                    "changePercent": "0"
                }
            ],
            "metadata": {
                "eventData": {
                    "indicatorSysid": "duplicate_server_records_indicator"
                },
                "previousScoreDate": new Date(new Date().getTime() - 86400000).getTime().toString(), // Yesterday
                "dataSourceLabel": "Number of duplicate server records",
                "changeArrow": "steady",
                "scoreDate": new Date().getTime().toString(),
                "filterQuery": field1 + "ISNOTEMPTY^" + field2 + "ISNOTEMPTY",
                "aggregate": {
                    "fieldType": "decimal"
                },
                "format": {
                    "unitFormat": "{0}",
                    "frequency": "daily",
                    "precision": 0
                },
                "entityType": "server",
                "duplicateRecords": result.duplicateDetails
            },
            "sparkline": {
                "data": [
                    {
                        "timestamp": new Date().getTime().toString(),
                        "value": result.totalDuplicateRecords.toString()
                    }
                ],
                "metadata": {
                    "eventData": {
                        "indicatorSysid": "duplicate_server_records_indicator"
                    },
                    "dataSourceLabel": "Number of duplicate server records",
                    "series": [
                        {
                            "label": "Duplicate servers",
                            "id": "value",
                            "type": "value"
                        }
                    ],
                    "aggregate": {
                        "fieldType": "decimal"
                    },
                    "format": {
                        "unitFormat": "{0}",
                        "frequency": "daily",
                        "precision": 0
                    }
                }
            }
        }
    ];
}
